#!/usr/bin/env bash
# GSZ step128 — Invoice + Receipt PDFs attached to order emails. Installs pdfkit,
# adds lib/pdfdocs.js (premium branded PDFs), gives the mailer attachment support,
# and attaches Invoice (confirm) + Invoice & Receipt (delivered). Safe + idempotent.
set -euo pipefail
GSZ=/opt/gsz; TS=$(date +%Y%m%d-%H%M%S); BK="$GSZ/.bak-step128-$TS"; TMP=$(mktemp -d)
PATCHED=(lib/mailer.js routes/checkout.js); NEW=(lib/pdfdocs.js)
echo "==> step128: Invoice + Receipt PDFs in email"
echo "==> ensuring pdfkit is installed"
( cd "$GSZ" && npm install pdfkit --no-audit --no-fund --silent ) || { echo "!! npm install pdfkit failed. Nothing changed."; exit 1; }
node -e "require('$GSZ/node_modules/pdfkit')" || { echo "!! pdfkit not loadable. Nothing changed."; exit 1; }
mkdir -p "$BK"; for f in "${PATCHED[@]}"; do mkdir -p "$BK/$(dirname "$f")"; cp "$GSZ/$f" "$BK/$f"; done
HAD_PDF=0; [ -f "$GSZ/lib/pdfdocs.js" ] && { HAD_PDF=1; cp "$GSZ/lib/pdfdocs.js" "$BK/pdfdocs.js"; }
echo "    backup: $BK"
restore(){ echo "!! FAILED — restoring"; for f in "${PATCHED[@]}"; do cp "$BK/$f" "$GSZ/$f"; done; if [ "$HAD_PDF" = "1" ]; then cp "$BK/pdfdocs.js" "$GSZ/lib/pdfdocs.js"; else rm -f "$GSZ/lib/pdfdocs.js"; fi; pm2 restart gsz >/dev/null 2>&1 || true; echo "!! restored."; }
trap 'restore' ERR
echo "" | base64 -d > "$TMP/p.js"
echo ""   | base64 -d > "$GSZ/lib/pdfdocs.js"
echo "==> applying patches"; node "$TMP/p.js" "$GSZ"
echo "==> validating"; node --check "$GSZ/lib/mailer.js"; node --check "$GSZ/routes/checkout.js"; node --check "$GSZ/lib/pdfdocs.js"
echo "==> smoke test: render a sample invoice"
( cd "$GSZ" && NODE_PATH="$GSZ/node_modules" node -e "const d=require('./lib/pdfdocs.js');d.invoice({order_no:'TEST',product_name:'X',plan_label:'1m',amount_display:100,currency:'Rs',email:'a@b.c',status:'paid'}).then(function(b){console.log('    invoice bytes:',b&&b.length);if(!b||b.length<500)process.exit(1);})" )
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz; sleep 2
CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true); [ "$CODE" = "200" ] && echo "    homepage 200: OK" || { echo "    homepage $CODE"; false; }
trap - ERR; rm -rf "$TMP"
echo ""; echo "==> step128 OK ✅  Order emails now attach a premium Invoice PDF (and a Receipt PDF on delivery). Credentials already appear in the delivery email body."
